package com.portfolio.financeflow.model;import jakarta.persistence.*;import jakarta.validation.constraints.*;@Entity @Table(name="budgets")public class Budget{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@NotBlank String category;@Positive double limitAmount;String month;public Long getId(){return id;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public double getLimitAmount(){return limitAmount;}public void setLimitAmount(double v){limitAmount=v;}public String getMonth(){return month;}public void setMonth(String v){month=v;}}
